const prose = document.getElementById('prose-acronyms');
const specPricing = document.getElementById('spec-pricing');
if (!prose || !specPricing) return false;

const isEnabled = document.getElementById('ai4a11y-abbr-styles') !== null;
if (!isEnabled) return true;

// Check that full expansion is written out in a span after first use
const fullSpans = prose.querySelectorAll('span.ai4a11y-abbr-full');
if (fullSpans.length === 0) return false;

const wcagSpan = [...fullSpans].find(s => s.textContent.includes('Web Content Accessibility Guidelines'));
const htmlSpan = [...fullSpans].find(s => s.textContent.includes('HyperText Markup Language'));
if (!wcagSpan || !htmlSpan) return false;

// In pricing, MSRP explanation should only include the part before comma
const pricingFullSpans = specPricing.querySelectorAll('span.ai4a11y-abbr-full');
const msrpSpan = [...pricingFullSpans].find(s => s.textContent.includes("manufacturer's suggested retail price"));
if (!msrpSpan) return false;

return true;

const prose = document.getElementById('prose-acronyms');
if (!prose) return false;

const isEnabled = document.getElementById('ai4a11y-abbr-styles') !== null;
if (isEnabled) {
  return prose.querySelectorAll('span.ai4a11y-abbr-full').length > 0;
} else {
  return prose.querySelectorAll('span.ai4a11y-abbr-full').length === 0 &&
         !prose.textContent.includes('(Web Content Accessibility Guidelines)');
}
